import static org.junit.Assert.*;

/**
 * Unit tests for ArrayRealVector.getLInfNorm().
 * Note: The implementation provided in the prompt contains a logic error:
 * max += Math.max(max, Math.abs(a));
 * This is not the standard L-infinity norm (which should be max(|a_i|)).
 * This test class follows the behavior of the provided code to ensure coverage.
 */
public class ArrayRealVector_getLInfNorm_TriageGen1Test {

    @Test
    public void testGetLInfNorm_EmptyVector() {
        // For an empty array, the loop won't execute, returning initial max = 0
        ArrayRealVector vector = new ArrayRealVector(new double[]{});
        Assert.assertEquals(0.0, vector.getLInfNorm(), 1e-10);
    }














}

